Input: {"question": "When and where was George Grimes born?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0489-530a17b24202:d00", "start": 0, "end": 9, "text": "George F."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0489-530a17b24202:d00", "start": 10, "end": 137, "text": "Grimes George Frederick Arthur Grimes (June 29, 1877 – August 10, 1929) was a businessman and political figure in Newfoundland."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0489-530a17b24202:d00", "start": 138, "end": 311, "text": "He represented Port de Grave from 1913 to 1919, Fogo from 1923 to 1924, Twillingate from 1924 to 1928 and Lewisporte from 1928 to 1929 in the Newfoundland House of Assembly."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0489-530a17b24202:d00", "start": 312, "end": 379, "text": "He was born in Channel, the son of William Grimes and Amelia White."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0489-530a17b24202:d00", "start": 380, "end": 403, "text": "The family moved to St."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0489-530a17b24202:d00", "start": 404, "end": 482, "text": "John's when Grimes was twelve after his father, a policeman, was posted there."}, "D1S7": {"document_number": 1, "doc_id": "ramdocs-0489-530a17b24202:d00", "start": 483, "end": 567, "text": "He was employed as a clerk from 1890 until 1902, when he became a department manager"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0489-530a17b24202:d01", "start": 0, "end": 141, "text": "George Grimes (Queensland politician) George Grimes (17 December 1835 – 28 January 1910) was a member of the Queensland Legislative Assembly."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0489-530a17b24202:d01", "start": 142, "end": 254, "text": "Grimes was born in Ashby-de-la-Zouch, Leicestershire, the son of William Grimes and his wife Mary (née Douglas)."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0489-530a17b24202:d01", "start": 255, "end": 460, "text": "After arriving in Australia in 1849 onboard the \"Chaseley\", he took up farming at Kurilpa with his brother Samuel in 1857 before moving to \"Coongoon\" at Fairfield where he grew arrowroot and sugar in 1863."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0489-530a17b24202:d01", "start": 461, "end": 558, "text": "On 16 June 1863 Grimes married Mary Rogers (died 1919) and together had a son and five daughters."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0489-530a17b24202:d01", "start": 559, "end": 612, "text": "Grimes died in January 1910 and his funeral proceeded"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0489-530a17b24202:d02", "start": 0, "end": 376, "text": ", Leicestershire , England Died 28 January 1910 ( 1910-01-28 ) ( aged 74 ) Fairfield , Queensland , Australia Resting place South Brisbane Cemetery Nationality English Australian Spouse Mary Rogers ( m.1863 d.1919 ) Relations Samuel Grimes ( brother ) Occupation Farmer George Grimes ( 17 December 1835 – 28 January 1910 ) was a member of the Queensland Legislative Assembly ."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0489-530a17b24202:d02", "start": 377, "end": 519, "text": "[ 1 ] Biography [ edit ] Grimes was born in Ashby-de-la-Zouch , Leicestershire , the son of William Grimes and his wife Mary ( née Douglas ) ."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0489-530a17b24202:d02", "start": 520, "end": 564, "text": "After arriving in Australia in 1849 on board"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0489-530a17b24202:d03", "start": 0, "end": 663, "text": "English Read Edit View history Tools Tools move to sidebar hide Actions Read Edit View history General What links here Related changes Upload file Permanent link Page information Cite this page Get shortened URL Download QR code Print/export Download as PDF Printable version In other projects Wikidata item Appearance move to sidebar hide From Wikipedia , the free encyclopedia Australian politician George Grimes Member of the Queensland Legislative Assembly for Bulimba In office 18 November 1876 – 29 November 1878 Preceded by James Johnston Succeeded by Frederick Swanwick Personal details Born George Grimes ( 1835-12-17 ) 17 December 1835 Ashby-de-la-Zouch"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0489-530a17b24202:d04", "start": 0, "end": 117, "text": "the civil war, describing himself as having \" for a long time wayted on His Majesty' s person as his sworne servant.\""}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0489-530a17b24202:d04", "start": 118, "end": 187, "text": "Grimes died at the age of about 52 and was buried on 15 October 1657."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0489-530a17b24202:d04", "start": 188, "end": 270, "text": "Grimes married Alice Lovell, daughter of Charles Lovell, of West Harling, Norfolk."}, "D5S4": {"document_number": 5, "doc_id": "ramdocs-0489-530a17b24202:d04", "start": 271, "end": 412, "text": "George Grimes (English politician) Sir George Grimes (1605–1657) was an English politician who sat in the House of Commons from 1628 to 1629."}, "D5S5": {"document_number": 5, "doc_id": "ramdocs-0489-530a17b24202:d04", "start": 413, "end": 470, "text": "He supported the Royalist cause in the English Civil War."}, "D5S6": {"document_number": 5, "doc_id": "ramdocs-0489-530a17b24202:d04", "start": 471, "end": 566, "text": "Grimes was the son of Sir Thomas Grimes and his wife Margaret More, daughter of Sir George More"}, "D6S1": {"document_number": 6, "doc_id": "ramdocs-0489-530a17b24202:d05", "start": 0, "end": 111, "text": ", James Johnston , Grimes won the November 1876 by-election [ 5 ] defeating his opponents McMaster and Thorne ."}, "D6S2": {"document_number": 6, "doc_id": "ramdocs-0489-530a17b24202:d05", "start": 112, "end": 192, "text": "He was defeated at the 1878 Queensland colonial election by Frederick Swanwick ."}, "D6S3": {"document_number": 6, "doc_id": "ramdocs-0489-530a17b24202:d05", "start": 193, "end": 268, "text": "[ 6 ] Grimes had also served as a councilor on the Stephens Shire Council ."}, "D6S4": {"document_number": 6, "doc_id": "ramdocs-0489-530a17b24202:d05", "start": 269, "end": 410, "text": "His brother , Samuel Grimes , was a long-serving member of the Queensland Parliament having represented the seat of Oxley for over 23 years ."}, "D6S5": {"document_number": 6, "doc_id": "ramdocs-0489-530a17b24202:d05", "start": 411, "end": 465, "text": "[ 7 ] References [ edit ] ^ a b `` Former Members '' ."}, "D6S6": {"document_number": 6, "doc_id": "ramdocs-0489-530a17b24202:d05", "start": 466, "end": 492, "text": "Parliament of Queensland ."}, "D6S7": {"document_number": 6, "doc_id": "ramdocs-0489-530a17b24202:d05", "start": 493, "end": 499, "text": "2015 ."}, "D6S8": {"document_number": 6, "doc_id": "ramdocs-0489-530a17b24202:d05", "start": 500, "end": 522, "text": "Retrieved 3 May 2016 ."}}, "original_cards": [{"doc_id": "ramdocs-0489-530a17b24202:d00", "card_id": "ramdocs-0489-530a17b24202:d00:c0", "entity": "George Frederick Arthur Grimes", "scope": "Birth details", "claim": "George Frederick Arthur Grimes was born on June 29, 1877 in Channel.", "answer": "June 29, 1877 in Channel", "quote": "Grimes George Frederick Arthur Grimes (June 29, 1877 – August 10, 1929) was a businessman and political figure in Newfoundland. He represented Port de Grave from 1913 to 1919, Fogo from 1923 to 1924, Twillingate from 1924 to 1928 and Lewisporte from 1928 to 1929 in the Newfoundland House of Assembly. He was born in Channel, the son of William Grimes and Amelia White.", "original_document_number": 1}], "current_answers": ["June 29, 1877 in Channel", "17 December 1835 in Ashby-de-la-Zouch, Leicestershire"], "candidate_answers": [{"candidate_id": "R0", "answer": "June 29, 1877 in Channel", "origin": "initial"}, {"candidate_id": "R1", "answer": "17 December 1835 in Ashby-de-la-Zouch, Leicestershire", "origin": "initial"}]}

